from string import Template

def genera_casi(modello, spessori, carichi):
    casi = {}
    for s in spessori:
        for F in carichi:
            casi[f"piastra_s{s}_F{F}.inp"] = modello.substitute(s=s, F=F)
    return casi

M = Template("spessore $s\ncarico $F\n")
print(list(genera_casi(M, [4, 6], [1000])))

import re

def statistiche_mesh(output):
    trovate = re.findall(r"(\d+) nodes (\d+) elements", output)
    if not trovate:
        raise RuntimeError("mesh non riuscita")
    nodi, elementi = trovate[-1]
    return int(nodi), int(elementi)

print(statistiche_mesh("Info : 1842 nodes 3790 elements"))
